+  </head>
+  <body>
+    <main class="page">
+      <div id="app"></div>
+    </main>
+
+    <script>
+      const quizData = [
+        {
+          id: "q1",
+          title: "Which of these are programming languages?",
+          helpText: "Select all that apply.",
+          options: [
+            { value: "python", label: "Python", detail: "A popular high-level language." },
+            { value: "html", label: "HTML", detail: "A markup language for web structure." },
+            { value: "javascript", label: "JavaScript", detail: "Commonly used for interactive web apps." },
+            { value: "css", label: "CSS", detail: "A stylesheet language for presentation." }
+          ]
+        },
+        {
+          id: "q2",
+          title: "Which languages are strongly associated with system programming?",
+          options: [
+            { value: "c", label: "C", detail: "Often used for operating systems and embedded software." },
+            { value: "rust", label: "Rust", detail: "Known for memory safety and performance." },
+            { value: "ruby", label: "Ruby", detail: "A productive language for web development." },
+            { value: "go", label: "Go", detail: "Frequently used for servers and infrastructure." }
+          ]
+        },
+        {
+          id: "q3",
+          title: "Which of these are typed programming languages?",
+          options: [
+            { value: "typescript", label: "TypeScript", detail: "Adds static typing to JavaScript." },
+            { value: "java", label: "Java", detail: "A statically typed language used in many environments." },
+            { value: "bash", label: "Bash", detail: "A shell scripting language." },
+            { value: "haskell", label: "Haskell", detail: "A statically typed functional language." }
+          ]
+        }
+      ];
+
+      function QuestionField(question) {
+        const help = question.helpText
+          ? `<p class="help-text">${question.helpText}</p>`
+          : "";
+
+        const options = question.options
+          .map(
+            (option) => `
+              <label class="option">
+                <input type="checkbox" name="${question.id}" value="${option.value}" />
+                <span>
+                  <strong>${option.label}</strong>
+                  <span>${option.detail}</span>
+                </span>
+              </label>
+            `
+          )
+          .join("");
+
+        return `
+          <div class="form-field">
+            <h2 class="question-title">${question.title}</h2>
+            ${help}
+            <div class="options" role="group" aria-label="${question.title}">
+              ${options}
+            </div>
+          </div>
+        `;
+      }
+
+      function Quiz() {
+        return `
+          <section class="quiz-card" aria-labelledby="quiz-title">
+            <p class="eyebrow">Knowledge check</p>
+            <h1 id="quiz-title">Computer Languages Quiz</h1>
+            <p class="subtitle">Choose every answer that fits. Each question supports multiple selections.</p>
+            <form id="quiz-form" novalidate>
+              ${quizData.map(QuestionField).join("")}
+              <div class="actions">
+                <button type="submit">Submit</button>
+                <p class="result" id="result" aria-live="polite">No answers submitted yet.</p>
+              </div>
+            </form>
+          </section>
+        `;
+      }
+
+      document.getElementById("app").innerHTML = Quiz();
+
+      document.getElementById("quiz-form").addEventListener("submit", (event) => {
+        event.preventDefault();
+
+        const resultEl = document.getElementById("result");
+        const summary = quizData
+          .map((question) => {
+            const selected = Array.from(
+              document.querySelectorAll(`input[name="${question.id}"]:checked`)
+            ).map((input) => input.value);
+            return `${question.id.toUpperCase()}: ${selected.length} selected`;
+          })
+          .join(" · ");
+
+        resultEl.innerHTML = `<strong>Submitted.</strong> ${summary}`;
+      });
+    </script>
+  </body>
+</html>
*** End Patch
