<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Computer Languages Quiz</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --panel: #ffffff;
        --text: #122033;
        --muted: #5c6b80;
        --border: #d9e2ef;
        --accent: #2563eb;
        --accent-soft: #e8f0ff;
        --shadow: 0 18px 50px rgba(18, 32, 51, 0.08);
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, #eaf1ff 0, transparent 34%),
          var(--bg);
      }

      .page {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 32px 16px;
      }

      .quiz-card {
        width: min(760px, 100%);
        background: var(--panel);
        border: 1px solid rgba(217, 226, 239, 0.9);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
        padding: 28px;
      }

      .eyebrow {
        margin: 0 0 8px;
        color: var(--accent);
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        font-size: 0.8rem;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.8rem, 3vw, 2.4rem);
        line-height: 1.15;
      }

      .subtitle {
        margin: 10px 0 0;
        color: var(--muted);
      }

      form {
        margin-top: 28px;
      }

      .form-field {
        padding: 20px 0;
        border-top: 1px solid var(--border);
      }

      .form-field:first-of-type {
        border-top: 0;
        padding-top: 0;
      }

      .question-title {
        margin: 0 0 8px;
        font-size: 1.05rem;
      }

      .help-text {
        margin: 0 0 14px;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .options {
        display: grid;
        gap: 10px;
      }

      .option {
        display: flex;
        gap: 12px;
        align-items: flex-start;
        padding: 14px 16px;
        border: 1px solid var(--border);
        border-radius: 14px;
        background: #fbfcfe;
        transition: border-color 0.15s ease, background 0.15s ease, transform 0.15s ease;
      }

      .option:hover {
        border-color: #b9c9e6;
        background: #f7faff;
        transform: translateY(-1px);
      }

      .option input {
        margin-top: 3px;
        width: 18px;
        height: 18px;
        accent-color: var(--accent);
      }

      .option strong {
        display: block;
        font-weight: 600;
      }

      .option span {
        color: var(--muted);
        font-size: 0.95rem;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 12px;
        align-items: center;
        margin-top: 24px;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(135deg, #2563eb, #1d4ed8);
        color: #fff;
        font: inherit;
        font-weight: 700;
        padding: 14px 22px;
        cursor: pointer;
        box-shadow: 0 10px 24px rgba(37, 99, 235, 0.22);
      }

      button:focus-visible,
      input:focus-visible {
        outline: 3px solid rgba(37, 99, 235, 0.28);
        outline-offset: 2px;
      }

      .result {
        margin: 0;
        color: var(--muted);
      }

      .result strong {
        color: var(--text);
      }

      @media (max-width: 640px) {
        .quiz-card {
          padding: 20px;
        }

        .option {
          padding: 12px 14px;
        }
      }
    </style>
  </head>
  <body>
    <main class="page">
      <div id="app"></div>
    </main>

    <script>
      const quizData = [
        {
          id: "q1",
          title: "Which of these are programming languages?",
          helpText: "Select all that apply.",
          options: [
            { value: "python", label: "Python", detail: "A popular high-level language." },
            { value: "html", label: "HTML", detail: "A markup language for web structure." },
            { value: "javascript", label: "JavaScript", detail: "Commonly used for interactive web apps." },
            { value: "css", label: "CSS", detail: "A stylesheet language for presentation." }
          ]
        },
        {
          id: "q2",
          title: "Which languages are strongly associated with system programming?",
          options: [
            { value: "c", label: "C", detail: "Often used for operating systems and embedded software." },
            { value: "rust", label: "Rust", detail: "Known for memory safety and performance." },
            { value: "ruby", label: "Ruby", detail: "A productive language for web development." },
            { value: "go", label: "Go", detail: "Frequently used for servers and infrastructure." }
          ]
        },
        {
          id: "q3",
          title: "Which of these are typed programming languages?",
          options: [
            { value: "typescript", label: "TypeScript", detail: "Adds static typing to JavaScript." },
            { value: "java", label: "Java", detail: "A statically typed language used in many environments." },
            { value: "bash", label: "Bash", detail: "A shell scripting language." },
            { value: "haskell", label: "Haskell", detail: "A statically typed functional language." }
          ]
        }
      ];

      function QuestionField(question) {
        const help = question.helpText
          ? `<p class="help-text">${question.helpText}</p>`
          : "";

        const options = question.options
          .map(
            (option) => `
              <label class="option">
                <input type="checkbox" name="${question.id}" value="${option.value}" />
                <span>
                  <strong>${option.label}</strong>
                  <span>${option.detail}</span>
                </span>
              </label>
            `
          )
          .join("");

        return `
          <div class="form-field">
            <h2 class="question-title">${question.title}</h2>
            ${help}
            <div class="options" role="group" aria-label="${question.title}">
              ${options}
            </div>
          </div>
        `;
      }

      function Quiz() {
        return `
          <section class="quiz-card" aria-labelledby="quiz-title">
            <p class="eyebrow">Knowledge check</p>
            <h1 id="quiz-title">Computer Languages Quiz</h1>
            <p class="subtitle">Choose every answer that fits. Each question supports multiple selections.</p>
            <form id="quiz-form" novalidate>
              ${quizData.map(QuestionField).join("")}
              <div class="actions">
                <button type="submit">Submit</button>
                <p class="result" id="result" aria-live="polite">No answers submitted yet.</p>
              </div>
            </form>
          </section>
        `;
      }

      document.getElementById("app").innerHTML = Quiz();

      document.getElementById("quiz-form").addEventListener("submit", (event) => {
        event.preventDefault();

        const resultEl = document.getElementById("result");
        const summary = quizData
          .map((question) => {
            const selected = Array.from(
              document.querySelectorAll(`input[name="${question.id}"]:checked`)
            ).map((input) => input.value);
            return `${question.id.toUpperCase()}: ${selected.length} selected`;
          })
          .join(" · ");

        resultEl.innerHTML = `<strong>Submitted.</strong> ${summary}`;
      });
    </script>
  </body>
</html>
