        color: var(--muted);
        font-size: 0.95rem;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 12px;
        align-items: center;
        margin-top: 24px;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(135deg, #2563eb, #1d4ed8);
        color: #fff;
        font: inherit;
        font-weight: 700;
        padding: 14px 22px;
        cursor: pointer;
        box-shadow: 0 10px 24px rgba(37, 99, 235, 0.22);
