          id: "q1",
          title: "Which of these are programming languages?",
          helpText: "Select all that apply.",
          options: [
            { value: "python", label: "Python", detail: "A popular high-level language." },
            { value: "html", label: "HTML", detail: "A markup language for web structure." },
            { value: "javascript", label: "JavaScript", detail: "Commonly used for interactive web apps." },
            { value: "css", label: "CSS", detail: "A stylesheet language for presentation." }
          ]
        },
        {
          id: "q2",
          title: "Which languages are strongly associated with system programming?",
          options: [
            { value: "c", label: "C", detail: "Often used for operating systems and embedded software." },
            { value: "rust", label: "Rust", detail: "Known for memory safety and performance." },
            { value: "ruby", label: "Ruby", detail: "A productive language for web development." },
            { value: "go", label: "Go", detail: "Frequently used for servers and infrastructure." }
          ]
        },
        {
          id: "q3",
          title: "Which of these are typed programming languages?",
          options: [
            { value: "typescript", label: "TypeScript", detail: "Adds static typing to JavaScript." },
            { value: "java", label: "Java", detail: "A statically typed language used in many environments." },
            { value: "bash", label: "Bash", detail: "A shell scripting language." },
            { value: "haskell", label: "Haskell", detail: "A statically typed functional language." }
          ]
        }
